import React from 'react';
import { isElement } from 'react-is';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';

export type SelectV2FilterProps = StylingProps &
  DataTestId & {
    /**
     * Flag indicating if the client-side filtering should be disabled or not.
     * @defaultValue false
     **/
    disableFiltering?: boolean;
    /** Defines the default filter string. */
    defaultValue?: string;
    /** Defines the filter string value. */
    value?: string;
    /** The callback is triggered when the filterValue changes. */
    onChange?: (filterValue: string) => void;
  };

export function SelectV2Filter(props: SelectV2FilterProps) {
  return null;
}
SelectV2Filter.displayName = 'SelectV2.Filter';

/**
 * Typeguard function that will check if a React.Node is a SelectV2.Filter
 * @internal
 */
export function _isFilter(
  child: React.ReactNode,
): child is React.ReactElement<SelectV2FilterProps> {
  if (isElement(child) && child.type === SelectV2Filter) {
    return true;
  }
  return false;
}
